/**
 * Honba Core Market Data
 * High-fidelity market dataset across India (NSE/BSE), US, Japan, and UK.
 */

export type CountryCode = 'IN' | 'US' | 'JP' | 'UK';

export interface MarketCountry {
  code: CountryCode;
  name: string;
  flag: string;
  currency: string;
  currencySymbol: string;
  primaryExchanges: string[];
}

