export type AssetType = 'stocks' | 'etf' | 'bonds' | 'mf' | 'index' | 'ipo';
export type TechnicalRating = 'Strong Buy' | 'Buy' | 'Neutral' | 'Sell' | 'Strong Sell';
export type MarketCapTier = 'mega' | 'large' | 'mid' | 'small';

export interface CandleData {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface Instrument {
  symbol: string;
  name: string;
  country: CountryCode;
  exchange: string;
  sector: string;
  industry: string;
  assetType?: AssetType;
  price: number;
  change: number;
  changePercent: number;
  volume: number;
  avgVolume30d: number;
  marketCap: number; // in base units
  marketCapTier: MarketCapTier;
  pe: number;
  forwardPe: number;
  pb: number;
  eps: number;
  dividendYield: number; // %
  high52: number;
  low52: number;
  rsi14: number;
  sma20: number;
  sma50: number;
  sma200: number;
  technicalRating: TechnicalRating;
  perf1W: number; // %
  perf1M: number; // %
  perf3M: number; // %
  perf1Y: number; // %
  revenueGrowth: number; // %
  netMargin: number; // %
  roce: number; // %
  roe: number; // %
  debtToEquity: number;
  deliverableQty?: number;
  deliveryPct?: number;
  sparkline: number[];
  history: CandleData[];
  description: string;

  // ETF & Mutual Fund & Bond domain fields
  aum?: number;
  expenseRatio?: number;
  baseExpenseRatio?: number;
  totalExpenseRatio?: number;
  catTotalExpenseRatio?: number;
  sharpeRatio?: number;
  catSharpeRatio?: number;
  cagr3y?: number;
  cagr5y?: number;
  nav?: number;
  navReturn?: number;
  focus?: string;
  brand?: string;
  schemeType?: string; // Growth, Liquid, Debt, Hybrid
  mfCategory?: string;
  riskometer?: string;

  // Bond fields
  ytw?: number;
  coupon?: number;
  couponType?: string;
  couponFreq?: string;
  maturityDate?: string;
  issuerType?: string;
  creditRating?: string;
}

// Generate realistic synthetic OHLCV candles
function generateCandles(basePrice: number, count = 40): CandleData[] {
  const candles: CandleData[] = [];
  let currentPrice = basePrice * 0.88;
  const now = new Date();
  
  for (let i = count - 1; i >= 0; i--) {
    const d = new Date(now);
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    
    const delta = (Math.random() - 0.48) * (currentPrice * 0.024);
    const open = Number(currentPrice.toFixed(2));
    const close = Number(Math.max(1, open + delta).toFixed(2));
    const high = Number((Math.max(open, close) + Math.random() * (open * 0.015)).toFixed(2));
    const low = Number((Math.min(open, close) - Math.random() * (open * 0.015)).toFixed(2));
    const volume = Math.floor(200000 + Math.random() * 800000);
    
    candles.push({
      time: dateStr,
      open,
      high,
      low,
      close,
      volume,
    });
    currentPrice = close;
  }
  return candles;
}

function generateSparkline(candles: CandleData[]): number[] {
  return candles.slice(-14).map((c) => c.close);
}

